import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {SwitchComponent} from "./switch.component";
import {PI_SWITCH_ACTION, PI_SWITCH_CARD} from "./switch.types";

export * from "./switch.types";

registerCardComponent({
  name: PI_SWITCH_CARD,
  component: SwitchComponent,
  events: actionTypesToEvents(PI_SWITCH_ACTION),
});

import React from "react";
import {type PiCardProps} from "@pihanga2/core";
import {Switch as SwitchUI} from "@/components/ui/switch";
import {Label} from "@/components/ui/label";
import {useFormContext} from "@/cards/form/form.context";
import type {PiSwitchEvents, PiSwitchProps} from "./switch.types";

export const SwitchComponent = (
  props: PiCardProps<PiSwitchProps, PiSwitchEvents>,
): React.ReactNode => {
  const {
    name,
    checked: propChecked = false,
    disabled,
    label,
    className,
    cardName,
    onChanged,
  } = props;

  // `id` and `invalid` may be injected by a parent pi/field card via
  // Pihanga's extra-prop forwarding.  They are not in the official type so
  // we read them through an escape hatch.
  const injectedId = (props as {id?: string}).id;

  // Detect if we are inside a pi/form card via React context.
  const form = useFormContext();
  const useFormData = form.isInForm && Boolean(name);

  const checked = useFormData
    ? Boolean(form.formData[name!] ?? false)
    : propChecked;

  function handleCheckedChange(newChecked: boolean) {
    if (useFormData) {
      form.handleChange(name!, newChecked);
    } else {
      onChanged({name, checked: newChecked});
    }
  }

  // Use the id injected by pi/field; fall back to a local id when standalone.
  const selfId = `${cardName}-${name ?? "switch"}`;
  const fieldId = injectedId ?? selfId;

  return (
    <div
      data-pihanga={cardName}
      className={`flex items-center gap-2 ${className ?? ""}`}
    >
      <SwitchUI
        id={fieldId}
        checked={checked}
        onCheckedChange={handleCheckedChange}
        disabled={disabled}
      />
      {label && (
        <Label htmlFor={fieldId} className="cursor-pointer select-none">
          {label}
        </Label>
      )}
    </div>
  );
};

import {
  createCardDeclaration,
  createOnAction,
  registerActions,
} from "@pihanga2/core";

export const PI_SWITCH_CARD = "pi/switch";

export const Switch = createCardDeclaration<PiSwitchProps, PiSwitchEvents>(
  PI_SWITCH_CARD,
);

export const PI_SWITCH_ACTION = registerActions(PI_SWITCH_CARD, ["changed"]);

export const onSwitchChanged = createOnAction<PiSwitchChangedEvent>(
  PI_SWITCH_ACTION.CHANGED,
);

/** @deprecated Use `onSwitchChanged` instead. */
export const onPiSwitchChanged = onSwitchChanged;

// ---------------------------------------------------------------------------
// Props & Events
// ---------------------------------------------------------------------------

export type PiSwitchProps = {
  /**
   * Field name used to bind to FormContext when inside a pi/form card.
   * When provided the component reads its checked state from form data and
   * writes back via form.handleChange.
   */
  name?: string;

  /**
   * Controlled checked state used in standalone mode (outside a Form).
   * Ignored when `name` is set and the component is inside a pi/form.
   */
  checked?: boolean;

  /** When true, the switch is disabled and non-interactive. */
  disabled?: boolean;

  /**
   * Optional label text rendered beside the switch.
   * The label is automatically associated with the switch via `htmlFor`.
   */
  label?: string;

  /** Extra Tailwind / CSS classes forwarded to the root wrapper element. */
  className?: string;
};

export type PiSwitchChangedEvent = {
  /** Field name, mirrors the `name` prop if provided. */
  name?: string;
  /** New checked state after the toggle. */
  checked: boolean;
};

export type PiSwitchEvents = {
  onChanged: PiSwitchChangedEvent;
};
